const tabId = 118779795;
const result = await browserjs(tabId, async () => {
  // 1. Get all 134 permits
  const permitsRes = await fetch('/api/search?size=200&fq=entity_type:permit').then(r => r.json());
  const permits = permitsRes.results;

  // Filter permits mentioning paddle / paddling / canoe / kayak
  const paddlePermits = permits.filter(p => {
    const text = `${p.name} ${p.description || ''} ${p.parent_name || ''}`.toLowerCase();
    return text.includes('paddle') || text.includes('paddling') || text.includes('canoe') || text.includes('kayak');
  }).map(p => ({
    entity_id: p.entity_id,
    name: p.name,
    parent_name: p.parent_name,
    parent_type: p.parent_type,
    city: p.city,
    state_code: p.state_code,
    org_name: p.org_name
  }));

  // 2. Search activitypass for paddle / paddling / canoe / kayak / boat
  const apPaddle = await fetch('/api/search?q=paddle&size=100&fq=entity_type:activitypass').then(r => r.json());
  const apPaddling = await fetch('/api/search?q=paddling&size=100&fq=entity_type:activitypass').then(r => r.json());
  const apCanoe = await fetch('/api/search?q=canoe&size=100&fq=entity_type:activitypass').then(r => r.json());
  const apKayak = await fetch('/api/search?q=kayak&size=100&fq=entity_type:activitypass').then(r => r.json());

  // Deduplicate activity passes
  const apMap = new Map();
  [...apPaddle.results, ...apPaddling.results, ...apCanoe.results, ...apKayak.results].forEach(r => {
    apMap.set(r.id, {
      id: r.id,
      name: r.name,
      parent_name: r.parent_name,
      entity_type: r.entity_type
    });
  });

  return {
    paddlePermitsCount: paddlePermits.length,
    paddlePermits,
    activityPassesCount: apMap.size,
    activityPasses: Array.from(apMap.values())
  };
});

