        id: item.id,
        entity_id: item.entity_id,
        entity_type: item.entity_type,
        name: item.name,
        parent_name: item.parent_name,
        parent_type: item.parent_type,
        org_name: item.org_name,
        city: item.city,
        state_code: item.state_code
