const tabId = 118779795;
const permitList = await browserjs(tabId, async () => {
  const res = await fetch('/api/search?size=200&fq=entity_type:permit').then(r => r.json());
  return res.results.map(r => ({ id: r.entity_id, name: r.name, parent_name: r.parent_name }));
});

console.log(`Total permits: ${permitList.length}`);

// Let's fetch their activities in batches of 25
const results = await browserjs(tabId, async (list) => {
  const out = [];
  const batchSize = 25;
  for (let i = 0; i < list.length; i += batchSize) {
    const batch = list.slice(i, i + batchSize);
    const promises = batch.map(item =>
      fetch(`/api/permits/${item.id}`)
        .then(r => r.ok ? r.json() : null)
        .then(data => {
          if (!data || !data.payload) return null;
          const p = data.payload;
          const acts = (p.activities || []).map(a => a.name);
          const hasPaddling = acts.some(a => /paddle|paddling|canoe|kayak/i.test(a));
          return {
            id: item.id,
            name: p.name,
            recarea_name: p.recarea_name,
            recareas: p.recareas,
            org_name: p.org_name,
            activities: acts,
            hasPaddling
          };
        })
        .catch(() => null)
    );
    const batchRes = await Promise.all(promises);
    out.push(...batchRes.filter(Boolean));
  }
  return out;
}, permitList);

const paddlingPermits = results.filter(r => r.hasPaddling);
console.log(`Permits with explicit Paddling activity: ${paddlingPermits.length}`);
console.log(JSON.stringify(paddlingPermits, null, 2));

