];

const feeSummary = await browserjs(tabId, async (ids) => {
  const list = [];
  for (const id of ids) {
    try {
      const res = await fetch(`/api/permits/${id}`).then(r => r.json());
      const p = res.payload;

      // Collect fees from divisions
      const allFees = [];
      if (p.divisions) {
        for (const divKey of Object.keys(p.divisions)) {
          const div = p.divisions[divKey];
          if (div.fees) {
            for (const f of div.fees) {
              allFees.push({
                description: f.description,
                amount: f.amount,
                type: f.type
              });
            }
          }
        }
      }

      // Also look for fee text in rules or need to know
      const feeSections = (p.rules || []).filter(r => /fee|cost|price|\$/i.test(r.description || ''));

      list.push({
        id: p.id,
        name: p.name,
        org_name: p.org_name,
        recarea_name: p.recarea_name,
        recareas: p.recareas,
        feesCount: allFees.length,
        sampleFees: allFees.slice(0, 10),
        rulesFees: feeSections.map(s => s.description?.slice(0, 200))
      });
    } catch (e) {
      list.push({ id, error: e.message });
    }
  }
  return list;
}, candidateIds);

