const tabId = 118779795;
const allPermitData = await browserjs(tabId, async () => {
  const res = await fetch('/api/search?size=200&fq=entity_type:permit').then(r => r.json());
  return res.results.map(p => {
    // Extract fee mentions from description
    const text = (p.description || '') + ' ' + (p.html_description || '');
    // Look for lines or sentences with fee, $, cost
    const feeSentences = text.match(/[^.?!;\n]*(\$|\bfee\b|\bcost\b)[^.?!;\n]*/gi) || [];

    return {
      id: p.entity_id,
      name: p.name,
      parent_name: p.parent_name,
      parent_type: p.parent_type,
      org_name: p.org_name,
      city: p.city,
      state_code: p.state_code,
      feeMatches: feeSentences.slice(0, 10).map(s => s.trim().replace(/\s+/g, ' '))
    };
  });
});

console.log(`Total permits loaded: ${allPermitData.length}`);
// Let's filter to permits that might be water/river/paddling/boating related
