const tabId = 118779795;
const searchAll = await browserjs(tabId, async () => {
  const queries = ['paddling', 'canoe', 'kayak', 'paddle', 'rafting', 'boating', 'river permit'];
  const allResults = [];
  for (const q of queries) {
    const res = await fetch(`/api/search?q=${encodeURIComponent(q)}&size=100&fq=entity_type:(permit%20OR%20activitypass)`).then(r => r.json());
    if (res.results) {
      allResults.push(...res.results);
    }
  }

  // Deduplicate by id
  const map = new Map();
  for (const item of allResults) {
    if (!map.has(item.id)) {
      map.set(item.id, {
        id: item.id,
        entity_id: item.entity_id,
        entity_type: item.entity_type,
        name: item.name,
        parent_name: item.parent_name,
        parent_type: item.parent_type,
        org_name: item.org_name,
        city: item.city,
        state_code: item.state_code
      });
    }
  }
  return Array.from(map.values());
});

console.log(`Total unique permit/activitypass items found across all queries: ${searchAll.length}`);
// Filter to items that belong to a PARK (National Park, State Park, Park)
const parkItems = searchAll.filter(item => {
  const text = `${item.name} ${item.parent_name || ''} ${item.org_name || ''}`.toLowerCase();
  return text.includes('park');
});

console.log(`Park items count: ${parkItems.length}`);
console.log(JSON.stringify(parkItems, null, 2));

