const tabId = 118779795;
const summary = await browserjs(tabId, async () => {
  const res = await fetch('/api/search?size=200&fq=entity_type:permit').then(r => r.json());

  const results = [];
  for (const p of res.results) {
    const text = `${p.name} ${p.parent_name || ''} ${p.description || ''}`.toLowerCase();
    const isWater = /paddle|paddling|canoe|kayak|boat|boating|raft|river|lake|watercraft|float/i.test(text);
    if (isWater) {
      results.push({
        id: p.entity_id,
        name: p.name,
        parent_name: p.parent_name,
        org_name: p.org_name,
        city: p.city,
        state_code: p.state_code,
        isWater
      });
    }
  }
  return results;
});

console.log(`Water-related permits: ${summary.length}`);
console.log(JSON.stringify(summary, null, 2));

